const GLOBAL_CH={
1:{name:"Globalization and Economic Integration",sub:"Definitions, viewpoints, world-systems theory, and key actors"},
2:{name:"Market Integration and the Interstate System",sub:"Financial institutions, global corporations, and international relations"},
3:{name:"Global Governance and Asian Regionalism",sub:"States, non-state actors, regional networks, ideologies, and Asian organizations"}};
const GLOBAL_NOTES={
1:[
{t:"Working definition of globalization",bullets:["Globalization is the process of increasing connections and interactions among people, countries, businesses, and cultures through trade, technology, communication, and the movement of people and ideas.","In simple terms, the world is becoming more connected. A phone can be designed in one country, manufactured in another, and used with services from elsewhere."]},
{t:"Competing conceptions",entries:[{term:"Globalists",parts:[["View","Globalization connects countries and makes the world increasingly interconnected."]]},{term:"Skeptics",parts:[["View","Globalization is less powerful than some claim because states retain control over their affairs."]]},{term:"Transformationalists",parts:[["View","Globalization is changing the world, but its effects differ from country to country."]] }]},
{t:"Philosophies behind definitions",entries:[{term:"Underlying philosophy",parts:[["Meaning","The basic beliefs or values behind a definition."]]},{term:"Market globalism",parts:[["Focus","Free trade, open markets, businesses, and economic growth."]]},{term:"Justice globalism",parts:[["Focus","Fairness, equality, human rights, and social justice; globalization should benefit ordinary people as well as wealthy countries and corporations."]]},{term:"Religious globalism",parts:[["Focus","Faith, religious values, and connections among people who share a religion. Some view secularism or consumerism as threats to religious values."]] }]},
{t:"Why definitions vary",note:"People emphasize different parts of globalization because their interests, experiences, and beliefs differ. A businessperson may focus on trade; an environmentalist may focus on cross-border connections and environmental effects. Globalization is multidimensional."},
{t:"Economic globalization",bullets:["National economies become more integrated through cross-border movement of goods, services, capital, technology, information, and people.","Drivers include lower transportation and communication costs, trade liberalization, and advances in finance and technology.","These forces enable global supply chains, international investment, and rapid sharing of knowledge.","Benefits include larger markets, foreign investment, and access to technology. Risks include exposure to global shocks and competition."]},
{t:"Modern world system",bullets:["Immanuel Wallerstein’s world-systems theory describes an interconnected capitalist world-economy organized through an international division of labor.","The system emerged around the 16th century and groups countries into core, semi-periphery, and periphery positions.","Core economies are dominant and industrialized; semi-periphery economies are intermediate; periphery regions are less developed and often export resources.","Countries’ economic, political, and social processes are shaped in part by their position in this hierarchy."]},
{t:"Actors that facilitate economic globalization",entries:[{term:"International economic organizations",parts:[["Examples and roles","IMF, World Bank, WTO, and OECD provide platforms for cooperation. The IMF supports financial stability; the World Bank supports long-term development; the WTO covers trade rules."]]},{term:"Multinational companies",parts:[["Role","Operate across countries, build supply chains, and transfer technology, knowledge, and capital, linking local economies to global markets."]]},{term:"Central banks",parts:[["Role","Influence trade, investment, and financial stability through money supply, interest rates, and exchange rates."]] }]},
{t:"A balanced stance on integration",bullets:["Integration can create jobs, cheaper products, new markets, and faster growth for developing countries.","Challenges include pressure on local businesses, widening income gaps, and economic dependence among countries.","A balanced position supports integration while promoting fair policies that protect workers and local industries."]}
],
2:[
{t:"Market integration",bullets:["Market integration connects countries’ or regions’ economies through exchange of goods, services, capital, and resources.","It lowers trade barriers such as tariffs and restrictions, encouraging international trade, cooperation, competition, and growth.","Example: easier trade among EU members lets businesses sell across borders more readily."]},
{t:"Global interstate system",bullets:["A network of independent, sovereign states and their political, economic, social, and diplomatic relationships.","States have their own governments, laws, and interests while depending on one another for trade, security, resources, technology, and cooperation.","The Philippines importing goods from China and exporting products elsewhere illustrates this system."]},
{t:"International financial institutions (IFIs)",entries:[{term:"IMF",parts:[["Role","Promotes monetary and financial stability and supports countries during economic problems."]]},{term:"World Bank",parts:[["Role","Supports long-term development, including infrastructure, education, healthcare, and poverty reduction."]]},{term:"WTO",parts:[["Role","Provides international trade rules and a framework for trade cooperation and disputes."]]},{term:"Four major IFI roles",parts:[["Summary","Financial support, economic stability, facilitating trade, and international cooperation."]] }]},
{t:"Growth of global market integration",bullets:["After World War II, the IMF, World Bank, and GATT helped rebuild the global economy and promote trade.","Integration expanded quickly in the 1990s through multinational companies, trade agreements, and the internet, alongside advances in technology and transportation."]},
{t:"Global corporations",bullets:["A global corporation operates in multiple countries; its headquarters, factories, suppliers, employees, and customers may be spread across borders.","Attributes: international operations; global market presence; cross-border supply chains; foreign direct investment; advanced technology; global workforce; global branding; large financial resources; cultural adaptability; and global strategic management.","Foreign direct investment (FDI) means direct investment in a business or operation in another country."]},
{t:"Institutions that govern international relations",note:"International relations are not governed by one world government. Intergovernmental organizations create forums, rules, and processes for cooperation and disputes.",entries:[{term:"UN and UN Security Council",parts:[["UN","A global forum for diplomacy, human rights, and conflict prevention."],["UNSC","Can make binding decisions to maintain peace, send peacekeepers, or impose sanctions."]]},{term:"NATO",parts:[["Role","A military alliance whose core principle is collective defense: an attack on one member is treated as an attack on all."]]},{term:"WTO, IMF, and World Bank",parts:[["Roles","The WTO sets trade rules; the IMF provides crisis loans and economic support; the World Bank funds development projects."]]},{term:"ICJ and ICC",parts:[["ICJ","Handles legal disputes between states, such as border disputes."],["ICC","Prosecutes individuals accused of serious international crimes, such as war crimes or genocide."]]},{term:"Regional organizations",parts:[["Examples","The EU is a European political and economic partnership; ASEAN promotes cooperation and stability in Southeast Asia; the AU supports unity and integration in Africa."]] }]},
{t:"Internationalism and globalism",entries:[{term:"Internationalism",parts:[["Meaning","The idea that countries should cooperate to solve shared problems and reach common goals."]]},{term:"Globalism",parts:[["Meaning","The idea that the world is increasingly interconnected and events in one place can affect people elsewhere."]] }]},
{t:"Challenges of integration",bullets:["Global integration can create growth opportunities, but may also deepen inequality, economic dependence, and competition among states.","Fair policies, effective cooperation, and responsible international relations help spread benefits and support stability."]}
],
3:[
{t:"Global governance and states",bullets:["Global governance is how countries and other international actors cooperate to manage issues that affect the world.","States are sovereign countries with governments, territories, and populations. They remain central because they make decisions and represent their countries internationally.","States make international rules; join organizations; protect national interests; cooperate on climate change, security, migration, and pandemics; and implement agreements through national laws and policies."]},
{t:"Intergovernmental organizations (IGOs)",note:"IGOs are groups formed by three or more sovereign states to address shared challenges. They create rules and platforms for cooperation.",entries:[{term:"WHO",parts:[["Role","Tracks diseases, coordinates pandemic responses, and establishes health guidelines."]]},{term:"UNESCO",parts:[["Role","Works on cultural heritage, education, science, and World Heritage Sites."]]},{term:"Interpol",parts:[["Role","Supports police cooperation and information sharing across borders."]]},{term:"IAEA",parts:[["Role","Monitors nuclear programs to support safe, peaceful uses of atomic energy."]] }]},
{t:"Non-state actors (NSAs)",bullets:["Individuals, groups, or organizations that operate independently of a government but influence society, politics, economics, or international affairs.","Examples include NGOs such as Amnesty International, Human Rights Watch, and the International Committee of the Red Cross; multinational companies; violent non-state actors; and influential individuals.","NSAs can provide humanitarian aid, promote human rights, create jobs, influence public opinion, and help address poverty, climate change, or disasters.","Negative impacts can include misinformation, corporate exploitation, terrorism and armed conflict, and conflict with government policies.","Violent non-state actors include militias and insurgents, private military companies, and cross-border criminal organizations."]},
{t:"Asian regionalism",bullets:["Increasing integration, cooperation, and economic interdependence among East, Southeast, and South Asian countries.","It is driven mainly by market forces, trade liberalization, and shared development goals rather than a single top-down political authority.","It can expand intra-Asian trade, integrate supply chains, strengthen financial resilience, support infrastructure, and contribute to jobs and poverty reduction.","ASEAN and RCEP help reduce tariff barriers. The Chiang Mai Initiative Multilateralization (CMIM) strengthens financial safety nets against monetary crises and currency fluctuations."]},
{t:"Product networks",bullets:["Different countries perform different stages of making the same product; raw materials, parts, and services cross borders before the finished product reaches consumers.","Example: a smartphone may be designed in one country, use components from several Asian countries, be assembled elsewhere, and then exported.","Product networks increase trade, investment, specialization, jobs, exports, and economic cooperation.","Disasters, conflicts, pandemics, or trade restrictions in one country can disrupt the network and affect others."]},
{t:"Political ideas in a globalized world",entries:[{term:"Populism",parts:[["Meaning","Frames politics as “the people versus the elites.” Left-wing populism may target corporate power and inequality; right-wing populism may target global elites and immigration."]]},{term:"Religious fundamentalism",parts:[["View","May argue that secularism has failed to provide moral guidance and seek to base laws on religious texts and traditions."]]},{term:"Neoliberalism",parts:[["View","Promotes a global free market with minimal state control, using privatization and deregulation. Critics say it can increase inequality and harm local industries or the environment."]]},{term:"Democratic socialism",parts:[["View","Combines democracy with a socialist economy; higher taxes on the wealthy fund public services such as healthcare, education, and welfare. The presentation links it to the Nordic Model."]]},{term:"Nationalism and globalism",parts:[["Nationalism","Emphasizes sovereignty, borders, and national identity."],["Globalism","Emphasizes international cooperation, human rights, and global trade."],["Debate","How to balance duties to one’s own citizens with responsibilities to the wider global community."]] }]},
{t:"Asian and regional organizations",entries:[{term:"ASEAN",parts:[["Focus","Promotes economic, political, and social cooperation among Southeast Asian countries and supports regional integration."]]},{term:"APEC",parts:[["Focus","Promotes trade, investment, and sustainable development across the Asia-Pacific through soft regionalism."]]},{term:"SAARC",parts:[["Focus","Supports economic and social cooperation in South Asia despite political hurdles."]]},{term:"ASEAN Plus Three (APT)",parts:[["Focus","Formed in 1997; connects ASEAN with China, Japan, and South Korea for East Asian macroeconomic cooperation."]]},{term:"Shanghai Cooperation Organisation (SCO)",parts:[["Focus","Created in 2001; a Eurasian political, economic, and security organization led by China, Russia, and Central Asian states."]]},{term:"Asian Development Bank (ADB)",parts:[["Focus","Reduces poverty in Asia and the Pacific through loans, technical assistance, and investments, including infrastructure."]] }]}
]};
